import {
  type DatePicker as DatePickerController,
  type DatePickerOptions,
  createDatePicker,
} from "@cssints/headless";
import { Portal } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { For, createContext, merge, omit, onCleanup, untrack, useContext } from "solid-js";
import { Button } from "./button.tsx";
import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

/** A civil date as `YYYY-MM-DD`; the primitive's own model is the day number behind it. */
const formatDate = (iso: string): string => {
  const [year = "1970", month = "01", day = "01"] = iso.split("-");
  return new Date(Date.UTC(Number(year), Number(month) - 1, Number(day))).toLocaleDateString(
    undefined,
    { dateStyle: "medium", timeZone: "UTC" },
  );
};

export interface DatePickerProps extends Omit<DatePickerOptions, "id"> {
  /** The primitive, once: a test fixture needs the month and the roving day; a page rarely does. */
  readonly onReady?: (picker: DatePickerController) => void;
  /** The trigger's visible text for a chosen day; the locale's medium date by default. */
  readonly format?: (iso: string) => string;
  readonly id?: string;
  readonly children?: JSX.Element;
}

export type DatePickerTriggerPartProps = PartProps;

export interface DatePickerTriggerProps extends Renderable<DatePickerTriggerPartProps, void> {
  readonly class?: string;
  /** The chosen day by default, or the accessible name while nothing is chosen. */
  readonly children?: JSX.Element;
}

export type DatePickerContentPartProps = PartProps;

export interface DatePickerContentProps extends Renderable<DatePickerContentPartProps, void> {
  readonly class?: string;
  /** A month of your own; without children the header and the 6x7 grid are the panel. */
  readonly children?: JSX.Element;
}

export type DatePickerHeaderPartProps = PartProps;

export interface DatePickerHeaderProps extends Renderable<DatePickerHeaderPartProps, void> {
  readonly class?: string;
  /** The nav buttons; the previous and the next month by default. */
  readonly children?: JSX.Element;
}

export type DatePickerTitlePartProps = PartProps;

export interface DatePickerTitleProps extends Renderable<DatePickerTitlePartProps, void> {
  readonly class?: string;
  /** `labels.month(year, month)` by default. */
  readonly children?: JSX.Element;
}

export type DatePickerNavPartProps = PartProps;

export interface DatePickerNavProps extends Renderable<DatePickerNavPartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export type DatePickerGridPartProps = PartProps;

export interface DatePickerGridProps extends Renderable<DatePickerGridPartProps, void> {
  readonly class?: string;
  /** Weeks of your own; without children the weekday row and the six day rows are the grid. */
  readonly children?: JSX.Element;
}

export type DatePickerWeekPartProps = PartProps;

export interface DatePickerWeekProps extends Renderable<DatePickerWeekPartProps, void> {
  /** Seven ISO days, in the grid's column order. */
  readonly week: ReadonlyArray<string>;
  readonly class?: string;
  /** Cells of your own; without children one `DatePickerDay` per day. */
  readonly children?: JSX.Element;
}

export type DatePickerWeekdayPartProps = PartProps;

export interface DatePickerWeekdayProps extends Renderable<DatePickerWeekdayPartProps, void> {
  /** The column, 0-6, in the shown week order. */
  readonly index: number;
  readonly class?: string;
  readonly children?: JSX.Element;
}

export type DatePickerDayPartProps = PartProps;

export interface DatePickerDayProps extends Renderable<DatePickerDayPartProps, void> {
  /** The day this cell shows, `YYYY-MM-DD`; the primitive owns its id, indices and announced state. */
  readonly iso: string;
  readonly class?: string;
  /** The day of the month by default. */
  readonly children?: JSX.Element;
}

export type DatePickerStatusPartProps = PartProps;

export interface DatePickerStatusProps extends Renderable<DatePickerStatusPartProps, void> {
  readonly class?: string;
  /** `labels.day(iso)` of the chosen day by default; the announcement itself. */
  readonly children?: JSX.Element;
}

const DatePickerContext = createContext<{
  readonly picker: DatePickerController;
  readonly format: (iso: string) => string;
  /** The two refs the primitive's `attach` needs: it wires them once both exist. */
  readonly connect: (part: "trigger" | "content", element: HTMLElement) => void;
  /** Moves the DOM focus to the roving day, after the month's cells have re-rendered. */
  readonly focusRoving: () => void;
}>();

// The same decision as the popover's: the primitive's panel is `position: absolute` with page-space coordinates, so it is
// portalled to the body, out of any `position: relative`, `transform` or `overflow: hidden` between it and the page. The cost
// is a client-only island and a measurement of the trigger per open. No `display`: `hidden` on the panel is what closes it.
const contentClass = css.cn(
  css.zIndex("var(--z-popover)"),
  css.width("max-content"),
  css.padding(t.space._2),
  css.bg(t.color.overlayBackground),
  css.color(t.color.text),
  css.border("1px solid", t.color.overlayBorder),
  css.borderRadius(t.radius.lg),
  css.boxShadow(t.shadow.popover),
  // the panel holds the grid, whose cells take the DOM focus: a ring around the panel is noise
  css.outline("none"),
);

const headerClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.gap(t.space._1),
  css.marginBlockEnd(t.space._2),
);

const titleClass = css.cn(
  css.margin("0"),
  css.marginInlineEnd("auto"),
  css.fontSize(t.font.size),
  css.fontWeight("600"),
  css.color(t.color.text),
);

// One row of seven equal columns; the weekday row and the six day rows line up because both are this class.
const rowClass = css.cn(
  css.display("grid"),
  css.gridTemplateColumns("repeat(7, 1fr)"),
  css.gap(t.space._1),
);

const gridClass = css.cn(css.display("grid"), css.gap(t.space._1));

const weekdayClass = css.cn(
  css.paddingBlockEnd(t.space._1),
  css.textAlign("center"),
  css.fontSize(t.font.sizeSm),
  css.fontWeight("500"),
  css.color(t.color.muted),
);

// The nav buttons are plain buttons, not the kit's `Button`: a `Button` owns `data-part="button"`, and these are parts of
// the calendar, so the skin keeps their name and the quiet, compact look itself.
const navClass = css.cn(
  css.padding(t.space._1, t.space._2),
  css.bg("transparent"),
  css.border("1px solid", "transparent"),
  css.borderRadius(t.radius.sm),
  css.fontSize(t.font.size),
  css.color(t.color.text),
  css.cursor("pointer"),
  css.hover(css.bg(t.color.buttonBackground)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
);

// The cell's state is the primitive's announcement: `aria-selected` for the chosen day, `aria-current="date"` for today,
// `aria-disabled` outside `min` / `max`. The kit paints those and keeps no copy of the value.
const dayClass = css.cn(
  css.display("grid"),
  css.placeItems("center"),
  css.minWidth("2.25rem"),
  css.minHeight("2.25rem"),
  css.borderRadius(t.radius.sm),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.text),
  css.cursor("pointer"),
  css.hover(css.bg(t.color.buttonBackground)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
  css.attr("aria-current", "date")(css.boxShadow("inset 0 0 0 1px", t.color.highlight)),
  css.attr("aria-selected", "true")(
    css.bg(t.color.highlight),
    css.color(t.color.onHighlight),
    css.hover(css.bg(t.color.highlightPressed)),
  ),
  css.attr("aria-disabled", "true")(css.color(t.color.textDisabled), css.cursor("not-allowed")),
);

// The chosen day's announcement, read by a screen reader: the region is in the page and visually hidden, never `hidden` (a
// hidden live region is not announced).
const statusClass = css.cn(
  css.position("absolute"),
  css.width("1px"),
  css.height("1px"),
  css.overflow("hidden"),
  css.clipPath("inset(50%)"),
  css.whiteSpace("nowrap"),
);

/**
 * A date picker, styled: `DatePicker.Trigger` opens `DatePicker.Content`, a calendar with `role="dialog"` around a 6x7
 * `role="grid"` of days. `createDatePicker` composes the popover, the grid and the status region: it owns the open state, the
 * month, the roving day, the day numbers, the keys (arrows, Home, End, PageUp, PageDown, Enter, Space, Escape), `min` / `max`,
 * the announcement of a chosen day, and the placement and light dismissal of the popup. The kit adds the trigger's visible
 * date, the panel's surface, the header with its nav buttons, the calendar grid's look, and the portal the primitive's
 * page-space placement needs.
 *
 * The skin carries its own parts rather than reusing the kit's `Popover`: `createDatePicker` owns a popover instance inside, and
 * the two would be separate controllers sharing only the trigger's id.
 */
export const DatePicker = (props: DatePickerProps): JSX.Element => {
  const picker = createDatePicker({
    get value() {
      return props.value;
    },
    defaultValue: props.defaultValue,
    get onValueChange() {
      return props.onValueChange;
    },
    get min() {
      return props.min;
    },
    get max() {
      return props.max;
    },
    today: props.today,
    get open() {
      return props.open;
    },
    get onOpenChange() {
      return props.onOpenChange;
    },
    labels: props.labels,
    id: props.id,
    get firstDayOfWeek() {
      return props.firstDayOfWeek;
    },
  });
  // structural, read once: it is the primitive for a test, not a signal
  untrack(() => props.onReady)?.(picker);
  // The primitive wires two elements and creates an effect, so it is attached from the parts' refs: `ref` travels with the
  // props, so a `render` that spreads them keeps the wiring. Its teardown runs with the root.
  let trigger: HTMLElement | undefined;
  let content: HTMLElement | undefined;
  let detach: (() => void) | undefined;
  const connect = (part: "trigger" | "content", element: HTMLElement): void => {
    if (part === "trigger") {
      trigger = element;
    } else {
      content = element;
    }
    if (trigger !== undefined && content !== undefined && detach === undefined) {
      detach = picker.attach(trigger, content);
    }
  };
  onCleanup(() => {
    detach?.();
    detach = undefined;
  });
  // The primitive moves the roving tab stop but not the DOM focus on a nav click (its own `focusRoving` runs on a key only).
  // The skin finishes the job on the next task, after the month's cells re-rendered, so the arrows keep working after a click.
  const focusRoving = (): void => {
    content?.querySelector<HTMLElement>('[role="gridcell"][tabindex="0"]')?.focus();
  };
  const format = (iso: string): string => (props.format ?? formatDate)(iso);
  return (
    <DatePickerContext value={{ picker, format, connect, focusRoving }}>
      {props.children}
      {/* the chosen day is announced even after the panel closed, so the region lives here and not in the panel */}
      <DatePickerStatus />
    </DatePickerContext>
  );
};

/** The button that opens the calendar: `Button` unless `render` says otherwise. Its text is the chosen day. */
export const DatePickerTrigger = (props: DatePickerTriggerProps): JSX.Element => {
  const { picker, format, connect } = useContext(DatePickerContext);
  const rest = omit(props, "render", "class", "children");
  const merged = merge(rest, picker.triggerProps, () => ({
    get class() {
      return css.cn(props.class);
    },
    ref: (element: HTMLElement) => {
      connect("trigger", element);
    },
  }));
  // an accessor, not a snapshot: Solid wraps the JSX interpolation in an effect, so the trigger's text follows the value
  const text = (): string => {
    const chosen = picker.value();
    return chosen === undefined ? picker.labels.trigger : format(chosen);
  };
  return renderPart(props, merged, undefined, (part) => (
    <Button {...part}>{props.children ?? text()}</Button>
  ));
};

/** The panel, portalled to the body and placed by the primitive. It is `hidden` while the calendar is closed. */
export const DatePickerContent = (props: DatePickerContentProps): JSX.Element => {
  const { picker, connect } = useContext(DatePickerContext);
  const merged = merge(omit(props, "render", "class", "children"), picker.popoverProps, () => ({
    "data-part": "date-picker",
    get class() {
      return css.cn(contentClass, props.class);
    },
    ref: (element: HTMLElement) => {
      connect("content", element);
    },
  }));
  return (
    <Portal>
      {renderPart(props, merged, undefined, (part) => (
        <div {...part} style={picker.contentStyle()}>
          {props.children ?? (
            <>
              <DatePickerHeader />
              <DatePickerGrid />
            </>
          )}
        </div>
      ))}
    </Portal>
  );
};

/** The row above the grid: the month's title and the nav buttons. */
export const DatePickerHeader = (props: DatePickerHeaderProps): JSX.Element => {
  const merged = merge(omit(props, "render", "class", "children"), () => ({
    "data-part": "date-picker-header",
    get class() {
      return css.cn(headerClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <div {...part}>
      <DatePickerTitle />
      {props.children ?? (
        <>
          <DatePickerPrevious />
          <DatePickerNext />
        </>
      )}
    </div>
  ));
};

/** The shown month, `labels.month(year, month)`; its id is what the grid and the popup are labelled by. */
export const DatePickerTitle = (props: DatePickerTitleProps): JSX.Element => {
  const { picker } = useContext(DatePickerContext);
  const merged = merge(omit(props, "render", "class", "children"), () => ({
    id: picker.headerProps.id,
    "data-part": "date-picker-title",
    get class() {
      return css.cn(titleClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <h2 {...part}>{props.children ?? picker.headerProps.text}</h2>
  ));
};

/** The previous month; either button pages the shown month and moves the roving day. */
export const DatePickerPrevious = (props: DatePickerNavProps): JSX.Element => {
  const { picker, focusRoving } = useContext(DatePickerContext);
  const merged = merge(omit(props, "render", "class", "children"), picker.previousProps, () => ({
    "data-part": "date-picker-previous",
    get class() {
      return css.cn(navClass, props.class);
    },
    onClick: () => {
      picker.previousProps.onClick();
      setTimeout(focusRoving, 0);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <button {...part}>{props.children ?? <span aria-hidden="true">‹</span>}</button>
  ));
};

/** The next month. */
export const DatePickerNext = (props: DatePickerNavProps): JSX.Element => {
  const { picker, focusRoving } = useContext(DatePickerContext);
  const merged = merge(omit(props, "render", "class", "children"), picker.nextProps, () => ({
    "data-part": "date-picker-next",
    get class() {
      return css.cn(navClass, props.class);
    },
    onClick: () => {
      picker.nextProps.onClick();
      setTimeout(focusRoving, 0);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <button {...part}>{props.children ?? <span aria-hidden="true">›</span>}</button>
  ));
};

/** The month: `role="grid"`, its row and column counts and the name of the month above it. */
export const DatePickerGrid = (props: DatePickerGridProps): JSX.Element => {
  const { picker } = useContext(DatePickerContext);
  const merged = merge(omit(props, "render", "class", "children"), picker.gridProps, () => ({
    "data-part": "date-picker-grid",
    get class() {
      return css.cn(gridClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <div {...part}>
      {props.children ?? (
        <>
          <div role="row" data-part="date-picker-row" class={rowClass}>
            <For each={[0, 1, 2, 3, 4, 5, 6]}>{(index) => <DatePickerWeekday index={index} />}</For>
          </div>
          <For each={picker.monthDays()}>{(week) => <DatePickerWeek week={week} />}</For>
        </>
      )}
    </div>
  ));
};

/** One week: `role="row"` and seven `DatePickerDay`s. */
export const DatePickerWeek = (props: DatePickerWeekProps): JSX.Element => {
  const merged = merge({ role: "row" as const }, () => ({
    "data-part": "date-picker-row",
    get class() {
      return css.cn(rowClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <div {...part}>{props.children ?? props.week.map((iso) => <DatePickerDay iso={iso} />)}</div>
  ));
};

/** A column's name: `role="columnheader"`, the primitive's short weekday (`abbr`) as its text. */
export const DatePickerWeekday = (props: DatePickerWeekdayProps): JSX.Element => {
  const { picker } = useContext(DatePickerContext);
  const weekday = picker.weekdayProps(props.index);
  const merged = merge(weekday, () => ({
    "data-part": "date-picker-weekday",
    get class() {
      return css.cn(weekdayClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <div {...part}>{props.children ?? part.abbr}</div>
  ));
};

/** One day: `role="gridcell"`, its indices, the roving tab stop and the chosen / today / disabled announcements. */
export const DatePickerDay = (props: DatePickerDayProps): JSX.Element => {
  const { picker } = useContext(DatePickerContext);
  const merged = merge(picker.cellProps(props.iso), () => ({
    "data-part": "date-picker-day",
    get class() {
      return css.cn(dayClass, props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <div {...part}>{props.children ?? String(Number(props.iso.slice(8)))}</div>
  ));
};

/** The chosen day's announcement: the primitive's polite `role="status"` region, visually hidden. */
export const DatePickerStatus = (props: DatePickerStatusProps): JSX.Element => {
  const { picker } = useContext(DatePickerContext);
  const merged = merge(omit(props, "render", "class", "children"), picker.statusProps, () => ({
    "data-part": "date-picker-status",
    get class() {
      return css.cn(statusClass, props.class);
    },
  }));
  const announcement = (): string | undefined => picker.status();
  return renderPart(props, merged, undefined, (part) => (
    <div {...part}>{props.children ?? announcement()}</div>
  ));
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { type DatePicker as DatePickerController } from "@cssints/headless";
import { render } from "@solidjs/web";

import { DatePicker, DatePickerContent, DatePickerTrigger } from "./date-picker.tsx";

/** A fixed "today", so a test never depends on when it runs: 2026-10-15, a Thursday. */
export const TODAY = "2026-10-15";

export interface DatePickerFixtureOptions {
  /** Controlled: the host owns the value. */
  readonly value?: string | undefined;
  /** Uncontrolled starting value. */
  readonly defaultValue?: string | undefined;
  readonly min?: string | undefined;
  readonly max?: string | undefined;
  /** The trigger's text; the ISO day by default, so an assertion does not depend on the locale. */
  readonly format?: (iso: string) => string;
}

export interface DatePickerMounted {
  readonly root: HTMLElement;
  readonly picker: DatePickerController;
  readonly dispose: () => void;
}

/**
 * Mounts the styled date picker in ordinary use: the trigger and the panel's default parts (header, nav, grid), with today
 * pinned and the trigger showing the ISO day. The panel is portalled, so the driver finds its parts on the document.
 */
export const mountDatePicker = (options: DatePickerFixtureOptions = {}): DatePickerMounted => {
  const root = document.createElement("div");
  document.body.append(root);
  let picker: DatePickerController | undefined;

  const dispose = render(
    () => (
      <DatePicker
        value={options.value}
        defaultValue={options.defaultValue}
        today={TODAY}
        min={options.min}
        max={options.max}
        format={options.format ?? ((iso) => iso)}
        onReady={(created) => {
          picker = created;
        }}
      >
        <DatePickerTrigger />
        <DatePickerContent />
      </DatePicker>
    ),
    root,
  );

  if (picker === undefined) {
    throw new Error("mountDatePicker: the picker did not render");
  }
  return {
    root,
    picker,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { type DatePickerMounted } from "./date-picker.fixture";

/**
 * The DOM side of the date picker's conformance test. `createDatePicker` is a composition whose oracle is its own browser
 * test, so there is no scenario walk here: this driver is what the kit's test reads — the trigger, the panel (portalled),
 * the grid's parts, a real click and key, and the element the DOM focus is on.
 */

/** Solid 2 delivers events through its delegated listener on a later turn. */
export const settle = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 20));

const required = <T extends HTMLElement>(parent: ParentNode, selector: string): T => {
  const element = parent.querySelector<T>(selector);
  if (element === null) {
    throw new Error(`date picker: no ${selector}`);
  }
  return element;
};

export const datePickerDriver = (mounted: DatePickerMounted) => {
  // the panel and the grid live in a portal, not under the trigger: they are found on the document
  const content = (): HTMLElement => required(document, '[data-part="date-picker"]');
  const grid = (): HTMLElement => required(content(), '[role="grid"]');
  const days = (): HTMLElement[] => [...grid().querySelectorAll<HTMLElement>('[role="gridcell"]')];
  return {
    trigger: (): HTMLButtonElement => required(mounted.root, '[aria-haspopup="dialog"]'),
    content,
    grid,
    title: (): HTMLElement => required(content(), '[data-part="date-picker-title"]'),
    status: (): HTMLElement => required(mounted.root, '[data-part="date-picker-status"]'),
    next: (): HTMLElement => required(content(), '[data-part="date-picker-next"]'),
    previous: (): HTMLElement => required(content(), '[data-part="date-picker-previous"]'),
    rows: (): HTMLElement[] => [...grid().querySelectorAll<HTMLElement>('[role="row"]')],
    weekdays: (): HTMLElement[] => [
      ...grid().querySelectorAll<HTMLElement>('[role="columnheader"]'),
    ],
    days,
    /** The day carrying the roving tab stop. */
    roving: (): HTMLElement | null => grid().querySelector<HTMLElement>('[tabindex="0"]'),
    open: async (): Promise<void> => {
      required<HTMLButtonElement>(mounted.root, '[aria-haspopup="dialog"]').click();
      await settle();
    },
    click: async (element: HTMLElement): Promise<void> => {
      // the raw DOM click, because a test driver refuses to press an `aria-disabled` day
      element.click();
      await settle();
    },
    /** A key on whatever holds the focus, as a reader's would arrive. */
    press: async (key: string, init: KeyboardEventInit = {}): Promise<KeyboardEvent> => {
      const target =
        document.activeElement instanceof HTMLElement ? document.activeElement : document.body;
      const event = new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true, ...init });
      target.dispatchEvent(event);
      await settle();
      return event;
    },
    style: (element: Element): CSSStyleDeclaration => getComputedStyle(element),
  };
};

import { afterEach, describe, expect, it } from "vite-plus/test";

import { TODAY, mountDatePicker, type DatePickerMounted } from "./date-picker.fixture";
import { datePickerDriver, settle } from "./date-picker-driver.ts";

const live: DatePickerMounted[] = [];

const mounted = (
  options: Parameters<typeof mountDatePicker>[0] = {},
): ReturnType<typeof datePickerDriver> & DatePickerMounted => {
  const instance = mountDatePicker(options);
  live.push(instance);
  return { ...datePickerDriver(instance), ...instance };
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

describe("Date picker (the kit's DOM)", () => {
  it("opens from the trigger into a portalled dialog around a named grid", async () => {
    const { root, picker, trigger, content, grid, title, rows, weekdays, days, roving, open } =
      mounted();
    expect(trigger().getAttribute("aria-haspopup")).toBe("dialog");
    expect(trigger().getAttribute("aria-expanded")).toBe("false");
    expect(trigger().getAttribute("aria-label")).toBe("Choose date");
    expect(content().hidden).toBe(true);

    await open();

    expect(root.contains(content())).toBe(false);
    expect(content().parentElement).toBe(document.body);
    expect(content().getAttribute("role")).toBe("dialog");
    expect(content().getAttribute("aria-modal")).toBeNull();
    expect(content().getAttribute("aria-labelledby")).toBe(title().id);
    expect(trigger().getAttribute("aria-expanded")).toBe("true");
    expect(grid().getAttribute("role")).toBe("grid");
    expect(grid().getAttribute("aria-rowcount")).toBe("6");
    expect(grid().getAttribute("aria-colcount")).toBe("7");
    expect(grid().getAttribute("aria-labelledby")).toBe(title().id);
    expect(title().textContent).toBe("October 2026");
    // 2026-10-01 is a Thursday, so the Monday-first window opens on 28 September
    expect(picker.monthDays()[0]?.[0]).toBe("2026-09-28");
    expect(rows()).toHaveLength(7);
    expect(weekdays()).toHaveLength(7);
    expect(weekdays()[0]?.getAttribute("role")).toBe("columnheader");
    expect(weekdays()[0]?.textContent).toBe("Mon");
    expect(days()).toHaveLength(42);
    // the roving tab stop is today, and opening took the DOM focus there
    expect(roving()?.textContent).toBe("15");
    expect(document.activeElement).toBe(roving());
  });

  it("places the panel under the trigger and paints it as a popover surface", async () => {
    const { trigger, content, open, style } = mounted();
    await open();
    await settle();
    const anchor = trigger().getBoundingClientRect();
    const panel = content().getBoundingClientRect();
    expect(Math.round(panel.top - window.scrollY)).toBe(Math.round(anchor.bottom + 4));
    const surface = style(content());
    // the panel is the theme's overlay surface, not a colour of the skin's own
    const probe = document.createElement("div");
    probe.style.backgroundColor = "var(--color-overlay-background)";
    document.body.append(probe);
    expect(surface.backgroundColor).toBe(style(probe).backgroundColor);
    probe.remove();
    expect(surface.borderTopWidth).toBe("1px");
    expect(surface.boxShadow).not.toBe("none");
    expect(surface.zIndex).toBe("10");
  });

  it("moves the focus and the roving stop by a day with the arrows", async () => {
    const { open, press, roving } = mounted();
    await open();
    const start = document.activeElement as HTMLElement;
    expect(start.textContent).toBe("15");
    expect(start.getAttribute("tabindex")).toBe("0");

    // the cursor move re-renders the month's cells, so the assertions read the element the focus landed on, not the old one
    await press("ArrowRight");
    const next = document.activeElement as HTMLElement;
    expect(next.textContent).toBe("16");
    expect(next.getAttribute("tabindex")).toBe("0");
    expect(roving()).toBe(next);

    await press("ArrowDown");
    expect((document.activeElement as HTMLElement).textContent).toBe("23");
    expect((document.activeElement as HTMLElement).getAttribute("tabindex")).toBe("0");
  });

  it("chooses the focused day, closes, labels the trigger and returns the focus", async () => {
    const { trigger, content, status, open, press } = mounted();
    await open();
    await press("ArrowRight");
    await press("Enter");

    expect(content().hidden).toBe(true);
    expect(trigger().getAttribute("aria-expanded")).toBe("false");
    expect(trigger().textContent).toBe("2026-10-16");
    expect(document.activeElement).toBe(trigger());
    // the announcement is the primitive's polite region, which the kit renders visually hidden
    expect(status().textContent).toBe("2026-10-16");
    expect(status().getAttribute("role")).toBe("status");
  });

  it("pages the month with the nav buttons and keeps the roving day", async () => {
    const { content, title, next, previous, open, click, days, roving } = mounted();
    await open();
    expect(title().textContent).toBe("October 2026");

    await click(next());
    expect(content().hidden).toBe(false);
    expect(title().textContent).toBe("November 2026");
    expect(days()).toHaveLength(42);
    // the cursor moved with the month and the DOM focus went to the new roving day
    expect(roving()?.textContent).toBe("15");
    expect(document.activeElement).toBe(roving());

    await click(previous());
    expect(title().textContent).toBe("October 2026");
  });

  it("paints the chosen day and today from their announcements", async () => {
    const { open, days, roving, style } = mounted({ defaultValue: "2026-10-10" });
    await open();
    const chosen = days().find((day) => day.getAttribute("aria-selected") === "true");
    const today = days().find((day) => day.getAttribute("aria-current") === "date");
    expect(chosen?.textContent).toBe("10");
    expect(roving()).toBe(chosen);
    expect(today?.textContent).toBe("15");
    // the chosen day has the highlight; today only a ring, so the two announcements paint differently
    const plain = chosen?.nextElementSibling as HTMLElement;
    expect(style(chosen as HTMLElement).backgroundColor).not.toBe(style(plain).backgroundColor);
    expect(style(today as HTMLElement).boxShadow).not.toBe("none");
    expect(style(today as HTMLElement).boxShadow).not.toBe(style(plain).boxShadow);
  });

  it("marks the days outside min and max as disabled, and refuses them", async () => {
    const { trigger, content, status, open, press, click, days, style } = mounted({
      defaultValue: "2026-10-15",
      min: "2026-10-10",
      max: "2026-10-20",
    });
    await open();
    const day = (text: string): HTMLElement | undefined =>
      days().find((cell) => cell.textContent === text);
    expect(day("9")?.getAttribute("aria-disabled")).toBe("true");
    expect(day("21")?.getAttribute("aria-disabled")).toBe("true");
    expect(day("10")?.getAttribute("aria-disabled")).toBeNull();
    expect(day("20")?.getAttribute("aria-disabled")).toBeNull();
    expect(style(day("9") as HTMLElement).cursor).toBe("not-allowed");
    expect(style(day("10") as HTMLElement).cursor).toBe("pointer");

    // a disabled day takes no click: no value, no close
    await click(day("9") as HTMLElement);
    expect(content().hidden).toBe(false);
    expect(trigger().textContent).toBe("2026-10-15");

    // Enter on the enabled roving day chooses it and closes
    await press("Enter");
    expect(content().hidden).toBe(true);
    expect(status().textContent).toBe(TODAY);
    expect(trigger().textContent).toBe("2026-10-15");
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
